package com.ianblk.zianmobs;
import com.ianblk.zianmobs.core.*;
import com.ianblk.zianmobs.core.Definitions.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
class ContentRetirementTest{
 private MobSpec mob(String id,String entity,String loot,Map<String,String> equipment){return new MobSpec(id,id,entity,25,3,0,0,0,List.of(),equipment,loot,false);}
 private ZoneSpec zone(String id,String... team){var c=new Point(0,64,0,0);var b=CenteredZone.bounds(c,8,8,4,2);return new ZoneSpec(id,"minecraft:overworld",b.first(),b.second(),List.of(c),List.of(team),1,5,60,"",true,c,8,8,4,2);}
 @Test void removesAliasedEntitiesAndOnlyDisablesAffectedZones(){var before=new Zones.Config(2,Map.of("alias",mob("alias","zianmobs:armored_grub","",Map.of()),"guard",mob("guard","minecraft:zombie","",Map.of())),Map.of(),Map.of("affected",zone("affected","alias","guard"),"safe",zone("safe","guard")));var migrated=ContentRetirement.migrate(before,s->false);assertFalse(migrated.config().mobs().containsKey("alias"));assertEquals(List.of("guard"),migrated.config().zones().get("affected").team());assertFalse(migrated.config().zones().get("affected").enabled());assertEquals(before.zones().get("safe"),migrated.config().zones().get("safe"));assertEquals(Set.of("affected"),migrated.affectedZones());assertEquals(migrated.config(),ContentRetirement.migrate(migrated.config(),s->false).config());}
 @Test void removesRetiredLootAndEquipmentWithoutChangingValidItems(){var retired=new LootEntry("bad",10,1,1);var kept=new LootEntry("good",50,2,3);var loot=new LootSpec("mixed","MOB",1,List.of(retired,kept),"");var before=new Zones.Config(2,Map.of("guard",mob("guard","minecraft:zombie","mixed",Map.of("head","bad","mainhand","good"))),Map.of("mixed",loot),Map.of("arena",zone("arena","guard")));var migration=ContentRetirement.migrate(before,"bad"::equals);assertEquals(List.of(kept),migration.config().loot().get("mixed").entries());assertEquals(Map.of("mainhand","good"),migration.config().mobs().get("guard").equipment());assertFalse(migration.config().zones().get("arena").enabled());}
 @Test void removesEmptyLootAndDetachesReferences(){var before=new Zones.Config(2,Map.of("guard",mob("guard","minecraft:zombie","removed",Map.of())),Map.of("removed",new LootSpec("removed","MOB",1,List.of(new LootEntry("bad",1,1,1)),"")),Map.of("arena",zone("arena","guard")));var after=ContentRetirement.migrate(before,s->true).config();assertTrue(after.loot().isEmpty());assertEquals("",after.mobs().get("guard").loot());assertFalse(after.zones().get("arena").enabled());}
 @Test void requestedRemovalListIsExactAndNamespaced(){assertEquals(28,ContentRetirement.ITEMS.size());assertEquals(2,ContentRetirement.ENTITIES.size());assertTrue(ContentRetirement.itemId("zianmobs:kraber_sniper"));assertFalse(ContentRetirement.itemId("othermod:kraber_sniper"));assertFalse(ContentRetirement.itemId("zianmobs:carnivoret_weapon_set_wing"));assertFalse(ContentRetirement.itemId("zianmobs:toffy_rupee"));}
}
